1	package com.maritime.platform.gateway.filter;
2	
3	import java.util.Set;
4	
5	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
6	
7	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
8	import org.springframework.cloud.gateway.filter.GlobalFilter;
9	import org.springframework.core.Ordered;
10	import org.springframework.core.annotation.Order;
11	import org.springframework.http.server.reactive.ServerHttpRequest;
12	import org.springframework.stereotype.Component;
13	import org.springframework.web.server.ServerWebExchange;
14	
15	import reactor.core.publisher.Mono;
16	
17	/**
18	 * Strips headers that must only be set by the gateway, never trusted from clients.
19	 * <p>
20	 * Runs for all requests &mdash; including public paths &mdash; before any
21	 * auth or logging filter sees the request, so no downstream component can be
22	 * tricked by client-supplied internal headers.
23	 * <p>
24	 * Configured HMAC signature headers are preserved so that
25	 * {@link HmacAuthenticationGatewayFilter} can read them before they are
26	 * stripped post-authentication.
27	 */
28	@Component
29	@Order(GatewayFilterOrder.UNTRUSTED_HEADER_STRIP)
30	public class UntrustedHeaderStripFilter implements GlobalFilter, Ordered {
31	
32		// Headers that must only be set by the gateway, never trusted from clients.
33		// HMAC signature headers are handled separately: they are preserved during
34		// the initial strip (so HMAC auth can read them) and removed after auth
35		// decision in HmacAuthenticationGatewayFilter.
36		static final Set<String> CONTEXT_HEADERS = Set.of(
37				"X-Internal-Call",
38				"X-User-Id", "X-User-Name",
39				"X-Active-Org-Code", "X-Active-Org-Name",
40				"X-Session-Id",
41				"X-System-Scope",
42				"X-User-Source",
43				"X-Tenant-Id", "X-Tenant-Code",
44				"X-App-Code", "X-App-Id",
45				"X-Verified-App-Code",
46				"X-App-Permissions",
47				"X-Trace-Id"
48		);
49	
50		private final GatewaySecurityProperties properties;
51	
52		public UntrustedHeaderStripFilter(GatewaySecurityProperties properties) {
53			this.properties = properties;
54		}
55	
56		@Override
57		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
58			Set<String> hmacHeaders = hmacHeaderNames();
59			ServerHttpRequest mutated = exchange.getRequest().mutate()
60					.headers(headers -> {
61						for (String h : CONTEXT_HEADERS) {
62							if (!hmacHeaders.contains(h)) {
63								headers.remove(h);
64							}
65						}
66					})
67					.build();
68			return chain.filter(exchange.mutate().request(mutated).build());
69		}
70	
71		/**
72		 * Returns the set of currently configured HMAC signature header names.
73		 * These are preserved during the untrusted-header strip so that the
74		 * HMAC authentication filter can read them.
75		 */
76		private Set<String> hmacHeaderNames() {
77			GatewaySecurityProperties.Headers hdrs = properties.getHmac().getHeaders();
78			return Set.of(
79					hdrs.getAppKey(),
80					hdrs.getTimestamp(),
81					hdrs.getNonce(),
82					hdrs.getBodyDigest(),
83					hdrs.getSignature()
84			);
85		}
86	
87		@Override
88		public int getOrder() {
89			return GatewayFilterOrder.UNTRUSTED_HEADER_STRIP;
90		}
91	}
