3	import java.util.UUID;
4	
5	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
6	import org.springframework.cloud.gateway.filter.GlobalFilter;
7	import org.springframework.core.Ordered;
8	import org.springframework.core.annotation.Order;
9	import org.springframework.stereotype.Component;
10	import org.springframework.web.server.ServerWebExchange;
11	
12	import reactor.core.publisher.Mono;
13	
14	@Component
15	@Order(GatewayFilterOrder.TRACE_ID)
16	public class TraceIdGatewayFilter implements GlobalFilter, Ordered {
17	
18		public static final String TRACE_ID_HEADER = "X-Trace-Id";
19	
20		public static final String TRACE_ID_ATTR = "gateway.traceId";
21	
22		@Override
23		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
24			String traceId = exchange.getRequest().getHeaders().getFirst(TRACE_ID_HEADER);
25			if (traceId == null || traceId.isBlank()) {
26				traceId = UUID.randomUUID().toString().replace("-", "");
27			}
28			exchange.getAttributes().put(TRACE_ID_ATTR, traceId);
29			exchange.getResponse().getHeaders().set(TRACE_ID_HEADER, traceId);
30			return chain.filter(exchange);
31		}
32	
33		@Override
34		public int getOrder() {
35			return GatewayFilterOrder.TRACE_ID;
36		}
37	}
