1	package com.maritime.platform.gateway.filter;
2	
3	import com.maritime.platform.gateway.security.GatewayPrincipal;
4	
5	import org.springframework.http.server.reactive.ServerHttpRequest;
6	import org.springframework.stereotype.Component;
7	
8	import java.util.List;
9	
10	/**
11	 * Writes verified identity headers onto the downstream request.
12	 * <p>
13	 * JWT-authenticated users get user-id, org, session, scope, and
14	 * source headers. HMAC-authenticated apps get app-code, tenant,
15	 * and permissions headers. Both paths always set every defined
16	 * header so downstream services can trust their presence.
17	 */
18	@Component
19	public class TrustedHeaderWriter {
20	
21		static final String X_USER_ID = "X-User-Id";
22		static final String X_USER_NAME = "X-User-Name";
23		static final String X_ACTIVE_ORG_CODE = "X-Active-Org-Code";
24		static final String X_ACTIVE_ORG_NAME = "X-Active-Org-Name";
25		static final String X_TENANT_ID = "X-Tenant-Id";
26		static final String X_SESSION_ID = "X-Session-Id";
27		static final String X_SYSTEM_SCOPE = "X-System-Scope";
28		static final String X_USER_SOURCE = "X-User-Source";
29	
30		static final String X_VERIFIED_APP_CODE = "X-Verified-App-Code";
31		static final String X_APP_CODE = "X-App-Code";
32		static final String X_APP_ID = "X-App-Id";
33		static final String X_TENANT_CODE = "X-Tenant-Code";
34		static final String X_APP_PERMISSIONS = "X-App-Permissions";
35	
36		public ServerHttpRequest.Builder writeUserHeaders(ServerHttpRequest.Builder builder,
37				GatewayPrincipal.User user) {
38			return builder
39					.header(X_USER_ID, nullToEmpty(user.userId()))
40					.header(X_USER_NAME, nullToEmpty(user.userName()))
41					.header(X_ACTIVE_ORG_CODE, nullToEmpty(user.activeOrgCode()))
42					.header(X_ACTIVE_ORG_NAME, nullToEmpty(user.activeOrgName()))
43					.header(X_TENANT_ID, nullToEmpty(user.tenantId()))
44					.header(X_SESSION_ID, nullToEmpty(user.sessionId()))
45					.header(X_SYSTEM_SCOPE, listToHeader(user.systemScope()))
46					.header(X_USER_SOURCE, nullToEmpty(user.userSource()));
47		}
48	
49		public ServerHttpRequest.Builder writeAppHeaders(ServerHttpRequest.Builder builder,
50				GatewayPrincipal.App app) {
51			return builder
52					.header(X_VERIFIED_APP_CODE, nullToEmpty(app.appCode()))
53					.header(X_APP_CODE, nullToEmpty(app.appCode()))
54					.header(X_APP_ID, nullToEmpty(app.appId()))
55					.header(X_TENANT_CODE, nullToEmpty(app.tenantCode()))
56					.header(X_TENANT_ID, nullToEmpty(app.tenantId()))
57					.header(X_APP_PERMISSIONS, listToHeader(app.permissions()));
58		}
59	
60		private static String nullToEmpty(String s) {
61			return s != null ? s : "";
62		}
63	
64		private static String listToHeader(List<String> list) {
65			return list != null && !list.isEmpty() ? String.join(",", list) : "";
66		}
67	}
