1	package com.maritime.platform.gateway.filter;
2	
3	import com.maritime.platform.gateway.security.GatewayPrincipal;
4	import com.maritime.platform.gateway.security.GatewayPrincipalHeaderCustomizer;
5	
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
8	import org.springframework.cloud.gateway.filter.GlobalFilter;
9	import org.springframework.core.Ordered;
10	import org.springframework.core.annotation.Order;
11	import org.springframework.http.server.reactive.ServerHttpRequest;
12	import org.springframework.stereotype.Component;
13	import org.springframework.web.server.ServerWebExchange;
14	
15	import reactor.core.publisher.Mono;
16	
17	import java.util.List;
18	
19	/**
20	 * Injects verified identity headers into the downstream request after
21	 * authentication has completed.
22	 * <p>
23	 * Trusted headers are stripped earlier in the chain by
24	 * {@link UntrustedHeaderStripFilter}, so any headers written here are
25	 * guaranteed to originate from the gateway starter.
26	 */
27	@Component
28	@Order(GatewayFilterOrder.CONTEXT_HEADER_INJECTION)
29	public class ContextHeaderInjectionFilter implements GlobalFilter, Ordered {
30	
31		private final TrustedHeaderWriter trustedHeaderWriter;
32		private final List<GatewayPrincipalHeaderCustomizer> customizers;
33	
34		public ContextHeaderInjectionFilter(TrustedHeaderWriter trustedHeaderWriter,
35				@Autowired(required = false) List<GatewayPrincipalHeaderCustomizer> customizers) {
36			this.trustedHeaderWriter = trustedHeaderWriter;
37			this.customizers = customizers != null ? customizers : List.of();
38		}
39	
40		@Override
41		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
42			GatewayPrincipal principal = exchange.getAttribute(GatewayPrincipal.ATTRIBUTE);
43			if (principal == null) {
44				return chain.filter(exchange);
45			}
46	
47			ServerHttpRequest.Builder builder = exchange.getRequest().mutate();
48			if (principal instanceof GatewayPrincipal.User user) {
49				trustedHeaderWriter.writeUserHeaders(builder, user);
50			} else if (principal instanceof GatewayPrincipal.App app) {
51				trustedHeaderWriter.writeAppHeaders(builder, app);
52			}
53	
54			for (GatewayPrincipalHeaderCustomizer customizer : customizers) {
55				customizer.customize(builder, principal);
56			}
57	
58			ServerHttpRequest mutated = builder.build();
59			return chain.filter(exchange.mutate().request(mutated).build());
60		}
61	
62		@Override
63		public int getOrder() {
64			return GatewayFilterOrder.CONTEXT_HEADER_INJECTION;
65		}
66	}
