50	    @Override
51	    public void afterPropertiesSet() {
52	        if (defaultAuthMode == AuthMode.JWT_AND_HMAC) {
53	            throw new IllegalStateException(
54	                    "maritime.gateway.security.default-auth-mode=JWT_AND_HMAC is reserved and not yet implemented");
55	        }
56	        for (RoutePolicy rp : routes) {
57	            if (rp.authMode == null) {
58	                throw new IllegalStateException(
59	                        "Route '" + rp.id + "' is missing required auth-mode. "
60	                        + "Set maritime.gateway.security.routes[" + routes.indexOf(rp) + "].auth-mode "
61	                        + "to one of: JWT, HMAC, JWT_OR_HMAC, NONE");
62	            }
63	            if (rp.authMode == AuthMode.JWT_AND_HMAC) {
64	                throw new IllegalStateException(
65	                        "Route '" + rp.id + "' uses JWT_AND_HMAC which is reserved and not yet implemented");
66	            }
67	        }
68	
69	        // Fail closed: auth mode must be consistent with enabled flags.
70	        // Without this check, a route requesting JWT/HMAC authentication
71	        // would silently forward requests when the corresponding filter
72	        // is not registered due to jwt.enabled=false / hmac.enabled=false.
73	        validateAuthModeConsistency(defaultAuthMode, "default-auth-mode");
74	        for (RoutePolicy rp : routes) {
75	            validateAuthModeConsistency(rp.authMode, "route '" + rp.id + "'");
76	        }
77	
78	        if (jwt.enabled) {
79	            if (jwt.secret == null || jwt.secret.isBlank()) {
80	                throw new IllegalStateException(
81	                        "maritime.gateway.security.jwt.secret must not be blank when jwt.enabled=true");
82	            }
83	            if (jwt.issuer == null || jwt.issuer.isBlank()) {
84	                throw new IllegalStateException(
85	                        "maritime.gateway.security.jwt.issuer must not be blank when jwt.enabled=true");
86	            }
87	        }
88	        if (hmac.enabled) {
89	            if (hmac.timestampTolerance == null || hmac.timestampTolerance.isNegative()) {
90	                throw new IllegalStateException(
91	                        "maritime.gateway.security.hmac.timestamp-tolerance must be a positive duration when hmac.enabled=true");
92	            }
93	            if (hmac.nonceTtl == null || hmac.nonceTtl.isNegative()) {
94	                throw new IllegalStateException(
95	                        "maritime.gateway.security.hmac.nonce-ttl must be a positive duration when hmac.enabled=true");
96	            }
97	        }
98	    }
99	
100	    private void validateAuthModeConsistency(AuthMode mode, String target) {
101	        switch (mode) {
102	            case JWT:
103	                if (!jwt.enabled) {
104	                    throw new IllegalStateException(
105	                            target + " is JWT but maritime.gateway.security.jwt.enabled is not true");
106	                }
107	                break;
108	            case HMAC:
109	                if (!hmac.enabled) {
110	                    throw new IllegalStateException(
111	                            target + " is HMAC but maritime.gateway.security.hmac.enabled is not true");
112	                }
113	                break;
114	            case JWT_OR_HMAC:
115	                if (!jwt.enabled || !hmac.enabled) {
116	                    throw new IllegalStateException(
117	                            target + " is JWT_OR_HMAC but requires both "
118	                            + "maritime.gateway.security.jwt.enabled=true and "
119	                            + "maritime.gateway.security.hmac.enabled=true");
120	                }
121	                break;
122	            case NONE:
123	            case JWT_AND_HMAC:
124	                // NONE: no auth components required.
125	                // JWT_AND_HMAC: already rejected above.
126	                break;
127	        }
128	    }
