7	import com.maritime.platform.gateway.security.RouteSecurityPolicy;
8	import com.maritime.platform.gateway.security.hmac.HmacAuthenticationManager;
9	import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
10	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
11	
12	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
13	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
14	import org.springframework.cloud.gateway.filter.GlobalFilter;
15	import org.springframework.core.Ordered;
16	import org.springframework.core.annotation.Order;
17	import org.springframework.core.io.buffer.DataBuffer;
18	import org.springframework.core.io.buffer.DataBufferUtils;
19	import org.springframework.http.server.reactive.ServerHttpRequest;
20	import org.springframework.http.server.reactive.ServerHttpRequestDecorator;
21	import org.springframework.stereotype.Component;
22	import org.springframework.web.server.ServerWebExchange;
23	
24	import reactor.core.publisher.Flux;
25	import reactor.core.publisher.Mono;
26	
27	/**
28	 * Authenticates system-to-system requests using HMAC-SHA256 signatures.
29	 * <p>
30	 * Reads the request body once to compute the SHA-256 digest, then caches it
31	 * in a decorated exchange so downstream filters and handlers can still read it.
32	 * Stores the mapped {@link GatewayPrincipal.App} in the exchange.
33	 */
34	@Component
35	@ConditionalOnProperty("maritime.gateway.security.hmac.enabled")
36	@Order(GatewayFilterOrder.HMAC_AUTHENTICATION)
37	public class HmacAuthenticationGatewayFilter implements GlobalFilter, Ordered {
38	
39		private final HmacAuthenticationManager authManager;
40		private final GatewaySecurityProperties properties;
41		private final GatewayErrorWriter errorWriter;
42	
43		public HmacAuthenticationGatewayFilter(HmacAuthenticationManager authManager,
44				GatewaySecurityProperties properties, GatewayErrorWriter errorWriter) {
45			this.authManager = authManager;
46			this.properties = properties;
47			this.errorWriter = errorWriter;
48		}
49	
50		@Override
51		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
52			RouteSecurityPolicy policy = exchange.getAttribute(RouteSecurityPolicyFilter.POLICY_ATTR);
53			if (policy == null) {
54				return chain.filter(exchange);
55			}
56	
57			AuthMode mode = policy.getAuthMode();
58	
59			if (mode == AuthMode.JWT_AND_HMAC) {
60				return errorWriter.write(exchange, GatewayAuthErrorCode.UNSUPPORTED_AUTH_MODE);
61			}
62	
63			if (mode != AuthMode.HMAC && mode != AuthMode.JWT_OR_HMAC) {
64				return chain.filter(stripHmacHeadersFromExchange(exchange));
65			}
66	
67			// JWT_OR_HMAC: when a Bearer token is present, JWT handles auth;
68			// skip HMAC to avoid interfering with the JWT path.
69			if (mode == AuthMode.JWT_OR_HMAC && hasBearerToken(exchange)) {
70				return chain.filter(stripHmacHeadersFromExchange(exchange));
71			}
72	
73			GatewaySecurityProperties.Headers hdrs = properties.getHmac().getHeaders();
74			String appKey = exchange.getRequest().getHeaders().getFirst(hdrs.getAppKey());
75			String timestamp = exchange.getRequest().getHeaders().getFirst(hdrs.getTimestamp());
76			String nonce = exchange.getRequest().getHeaders().getFirst(hdrs.getNonce());
77			String bodyDigest = exchange.getRequest().getHeaders().getFirst(hdrs.getBodyDigest());
78			String signature = exchange.getRequest().getHeaders().getFirst(hdrs.getSignature());
79	
80			if (isAnyBlank(appKey, timestamp, nonce, bodyDigest, signature)) {
81				return errorWriter.write(exchange, GatewayAuthErrorCode.MISSING_HMAC_HEADERS);
82			}
83	
84			return readAndCacheBody(exchange)
85					.flatMap(cachedExchange -> {
86						byte[] bodyBytes = cachedExchange.getAttribute("gateway.cachedBody");
87						String method = exchange.getRequest().getMethod().name();
88						String rawPath = exchange.getRequest().getURI().getRawPath();
89						String rawQuery = exchange.getRequest().getURI().getRawQuery();
90	
91						return authManager.authenticate(appKey, timestamp, nonce, bodyDigest, signature,
92										method, rawPath, rawQuery, bodyBytes != null ? bodyBytes : new byte[0])
93								.flatMap(principal -> {
94									cachedExchange.getAttributes().put(GatewayPrincipal.ATTRIBUTE, principal);
95									// Strip raw HMAC signature headers before forwarding downstream
96									ServerHttpRequest stripped = stripHmacHeaders(
97											cachedExchange.getRequest(), hdrs, exchange);
98									return chain.filter(cachedExchange.mutate().request(stripped).build());
99								})
100								.onErrorResume(JwtAuthenticationException.class,
101										e -> errorWriter.write(cachedExchange, e.getErrorCode()));
102					});
103		}
104	
105		@Override
106		public int getOrder() {
107			return GatewayFilterOrder.HMAC_AUTHENTICATION;
108		}
109	
110		/**
111		 * Removes raw HMAC signature headers from the request before forwarding
112		 * downstream. Preserves any body decorator so the cached body stays readable.
113		 */
114		private ServerHttpRequest stripHmacHeaders(ServerHttpRequest request,
115				GatewaySecurityProperties.Headers hdrs, ServerWebExchange exchange) {
116			ServerHttpRequest headerStripped = request.mutate()
117					.headers(h -> {
118						h.remove(hdrs.getAppKey());
119						h.remove(hdrs.getTimestamp());
120						h.remove(hdrs.getNonce());
121						h.remove(hdrs.getBodyDigest());
122						h.remove(hdrs.getSignature());
123					})
124					.build();
125			return new ServerHttpRequestDecorator(headerStripped) {
126				@Override
127				public Flux<DataBuffer> getBody() {
128					return headerStripped.getBody();
129				}
130			};
131		}
132	
133		/**
134		 * Returns a new exchange whose request has all configured HMAC signature
135		 * headers removed. Used on pass-through paths (NONE, JWT, JWT_OR_HMAC
136		 * with Bearer) to ensure raw signature material never reaches downstream.
137		 */
138		private ServerWebExchange stripHmacHeadersFromExchange(ServerWebExchange exchange) {
139			GatewaySecurityProperties.Headers hdrs = properties.getHmac().getHeaders();
140			ServerHttpRequest stripped = exchange.getRequest().mutate()
141					.headers(h -> {
142						h.remove(hdrs.getAppKey());
143						h.remove(hdrs.getTimestamp());
144						h.remove(hdrs.getNonce());
145						h.remove(hdrs.getBodyDigest());
146						h.remove(hdrs.getSignature());
147					})
148					.build();
149			return exchange.mutate().request(stripped).build();
150		}
151	
152		/**
153		 * Reads the request body once, caches the bytes, and returns a decorated exchange
154		 * whose request body can be re-read by downstream filters and handlers.
155		 */
156		private Mono<ServerWebExchange> readAndCacheBody(ServerWebExchange exchange) {
157			return DataBufferUtils.join(exchange.getRequest().getBody())
158					.map(buf -> {
159						byte[] bytes = new byte[buf.readableByteCount()];
160						buf.read(bytes);
161						DataBufferUtils.release(buf);
162						return bytes;
163					})
164					.switchIfEmpty(Mono.just(new byte[0]))
165					.map(bytes -> {
166						ServerHttpRequest decorated = new ServerHttpRequestDecorator(exchange.getRequest()) {
167							@Override
168							public Flux<DataBuffer> getBody() {
169								return Flux.just(
170										exchange.getResponse().bufferFactory().wrap(bytes));
171							}
172						};
173						ServerWebExchange cached = exchange.mutate().request(decorated).build();
174						cached.getAttributes().put("gateway.cachedBody", bytes);
175						return cached;
176					});
177		}
178	
179		private boolean hasBearerToken(ServerWebExchange exchange) {
180			String auth = exchange.getRequest().getHeaders().getFirst("Authorization");
181			return auth != null && auth.startsWith("Bearer ");
182		}
183	
184		private boolean isAnyBlank(String... values) {
185			for (String v : values) {
186				if (v == null || v.isBlank()) {
187					return true;
188				}
189			}
190			return false;
191		}
192	
193	}
