552				GatewayPrincipal.User user = new GatewayPrincipal.User(
553						"real-user", "RealName", "real-session",
554						"ORG-REAL", "Real Org",
555						List.of("user"),
556						"SSO", "tenant-real");
557	
558				MockServerWebExchange exchange = MockServerWebExchange.from(
559						MockServerHttpRequest.get("/api/secure")
560								.header("X-User-Id", "forged-user")
561								.header("X-User-Name", "Hacker")
562								.header("X-Session-Id", "fake-session")
563								.header("X-Active-Org-Code", "EVIL")
564								.header("X-Active-Org-Name", "Evil Corp")
565								.header("X-Tenant-Id", "fake-tenant")
566								.header("X-System-Scope", "admin,root")
567								.header("X-User-Source", "internal"));
568	
569				// Step 1: strip untrusted headers
570				AtomicReference<ServerWebExchange> afterStrip = new AtomicReference<>();
571				strip.filter(exchange, capturingChain(afterStrip)).block();
572				ServerWebExchange stripped = afterStrip.get();
573	
574				// All forged headers must be gone
575				var strippedHeaders = stripped.getRequest().getHeaders();
576				assertThat(strippedHeaders.getFirst("X-User-Id")).isNull();
577				assertThat(strippedHeaders.getFirst("X-User-Name")).isNull();
578				assertThat(strippedHeaders.getFirst("X-Session-Id")).isNull();
579	
580				// Step 2: set the verified principal
581				GatewayPrincipal.User verifiedUser = new GatewayPrincipal.User(
582						"real-user", "RealName", "real-session",
583						"ORG-REAL", "Real Org",
584						List.of("user"),
585						"SSO", "tenant-real");
586				stripped.getAttributes().put(GatewayPrincipal.ATTRIBUTE, verifiedUser);
587	
588				// Step 3: inject trusted headers
589				AtomicReference<ServerWebExchange> afterInjection = new AtomicReference<>();
590				inject.filter(stripped, capturingChain(afterInjection)).block();
591				ServerWebExchange finalExchange = afterInjection.get();
592	
593				var finalHeaders = finalExchange.getRequest().getHeaders();
594				assertThat(finalHeaders.getFirst("X-User-Id")).isEqualTo("real-user");
595				assertThat(finalHeaders.getFirst("X-User-Name")).isEqualTo("RealName");
596				assertThat(finalHeaders.getFirst("X-Session-Id")).isEqualTo("real-session");
597				assertThat(finalHeaders.getFirst("X-Active-Org-Code")).isEqualTo("ORG-REAL");
598				assertThat(finalHeaders.getFirst("X-Tenant-Id")).isEqualTo("tenant-real");
599			}
600	
601			@Test
602			@DisplayName("forged app headers stripped, then HMAC-injected headers prevail")
603			void forgedAppHeadersStrippedAndInjected() {
604				UntrustedHeaderStripFilter strip = new UntrustedHeaderStripFilter(new GatewaySecurityProperties());
605				TrustedHeaderWriter writer = new TrustedHeaderWriter();
606				ContextHeaderInjectionFilter inject = new ContextHeaderInjectionFilter(writer, null);
607	
608				GatewayPrincipal.App app = new GatewayPrincipal.App(
609						"real-app-key", "real-app-code", "real-app-id",
610						"real-tenant", "RT001", List.of("read"));
611	
612				MockServerWebExchange exchange = MockServerWebExchange.from(
613						MockServerHttpRequest.get("/openapi/data")
614								.header("X-App-Code", "forged-app")
615								.header("X-App-Id", "999")
616								.header("X-Tenant-Code", "HACKED")
617								.header("X-Tenant-Id", "fake-tenant")
618								.header("X-Verified-App-Code", "forged-verified")
619								.header("X-App-Permissions", "admin,delete"));
620	
621				// Step 1: strip
622				AtomicReference<ServerWebExchange> afterStrip = new AtomicReference<>();
623				strip.filter(exchange, capturingChain(afterStrip)).block();
624				ServerWebExchange stripped = afterStrip.get();
625	
626				assertThat(stripped.getRequest().getHeaders().getFirst("X-App-Code")).isNull();
627				assertThat(stripped.getRequest().getHeaders().getFirst("X-App-Id")).isNull();
628	
629				// Step 2: set principal
630				stripped.getAttributes().put(GatewayPrincipal.ATTRIBUTE, app);
631	
632				// Step 3: inject
633				AtomicReference<ServerWebExchange> afterInjection = new AtomicReference<>();
634				inject.filter(stripped, capturingChain(afterInjection)).block();
635				ServerWebExchange finalExchange = afterInjection.get();
636	
637				var finalHeaders = finalExchange.getRequest().getHeaders();
638				assertThat(finalHeaders.getFirst("X-Verified-App-Code")).isEqualTo("real-app-code");
639				assertThat(finalHeaders.getFirst("X-App-Code")).isEqualTo("real-app-code");
640				assertThat(finalHeaders.getFirst("X-App-Id")).isEqualTo("real-app-id");
641				assertThat(finalHeaders.getFirst("X-Tenant-Code")).isEqualTo("RT001");
642				assertThat(finalHeaders.getFirst("X-Tenant-Id")).isEqualTo("real-tenant");
643				assertThat(finalHeaders.getFirst("X-App-Permissions")).isEqualTo("read");
644			}
645	
646			@Test
647			@DisplayName("forged headers stripped even when no auth principal (public paths)")
648			void forgedHeadersStrippedEvenWithoutAuth() {
649				UntrustedHeaderStripFilter strip = new UntrustedHeaderStripFilter(new GatewaySecurityProperties());
650				TrustedHeaderWriter writer = new TrustedHeaderWriter();
651				ContextHeaderInjectionFilter inject = new ContextHeaderInjectionFilter(writer, null);
652	
653				MockServerWebExchange exchange = MockServerWebExchange.from(
654						MockServerHttpRequest.get("/public/health")
655								.header("X-User-Id", "forged-user")
656								.header("X-App-Code", "forged-app")
657								.header("X-Tenant-Id", "fake-tenant"));
658	
659				// Strip
660				AtomicReference<ServerWebExchange> afterStrip = new AtomicReference<>();
661				strip.filter(exchange, capturingChain(afterStrip)).block();
662				ServerWebExchange stripped = afterStrip.get();
663	
664				// No principal on public path
665				assertThat((Object) stripped.getAttribute(GatewayPrincipal.ATTRIBUTE)).isNull();
666	
667				// Inject (should pass through since no principal)
668				AtomicReference<ServerWebExchange> afterInjection = new AtomicReference<>();
669				inject.filter(stripped, capturingChain(afterInjection)).block();
670				ServerWebExchange finalExchange = afterInjection.get();
671	
672				var finalHeaders = finalExchange.getRequest().getHeaders();
673				assertThat(finalHeaders.getFirst("X-User-Id")).isNull();
674				assertThat(finalHeaders.getFirst("X-App-Code")).isNull();
675				assertThat(finalHeaders.getFirst("X-Tenant-Id")).isNull();
676			}
677		}
678	
679		// ---------- helpers ----------
680	
681		private static GatewayFilterChain capturingChain(AtomicReference<ServerWebExchange> ref) {
682			return exchange -> {
683				if (ref != null) {
684					ref.set(exchange);
685				}
686				return Mono.empty();
687			};
688		}
689	}
